DECLARE @BatchStatusId INT,
@EventTypeId INT,
@EventSeverityId INT,
@ModuleId INT,
@BatchCategoryID INT,
@BatchId INT,
@Msg VARCHAR(200)

SET @BatchCategoryID= @BatchCategoryID

SET @BatchId= @BatchId

SET @Msg = 'Re-Sending TC Invoice Balancing Mail for GBDMA for BatchId -' + CONVERT(VARCHAR(20),@BatchId)

SET @EventTypeId = (
	SELECT EventTypeId
	FROM GENERIC.EventType
	WHERE EventType = 'SSIS'
) 

SET @EventSeverityId = ( 
	SELECT EventSeverityId 
	FROM GENERIC.EventSeverity
	WHERE EventSeverity = 'Informational'
)

SET @ModuleId = (
	SELECT ModuleId
	FROM GENERIC.Module 
	WHERE ModuleName = 'Trancentra'
) 


SET @BatchStatusId=(SELECT BatchStatusId FROM Invoice.BatchStatus where BatchStatus='Complete' AND ISValid=1)
IF(SELECT TOP 1 BatchId  AS RecordCount  FROM Invoice.Batch  where [FileName] IS NOT NULL AND BatchStatusId=@BatchStatusId AND BatchCategoryID=@BatchCategoryID  ORDER BY BatchId DESC)>0
BEGIN
	EXEC [GENERIC].[Pr_UpdateEventLog] 
		@EventTypeId, 
		@EventSeverityId, 
		@ModuleId,@Msg
END

